#pragma once
/**
 * @file SolveStationsRunEnd.hpp
 * @brief Run-end report of the stations in the solve.
 *
 * The run-end reports defined in SolveStationsRunEnd.cpp; each is a row of kNetworkRunEndReports
 * (network/runend/RunEnd.hpp).
 */

namespace GnssProcessor {

// ---- Run-end reports (generated by scripts/nom_td_cut.py) ----

struct NetworkRunEndView;

/**
 * @brief Run-end report: stations in the solve and the addStation PD rejections.
 *
 * The stations in the solve on every run (the in-solve count's minimum,
 * median and maximum, the PD drops and the re-admissions), and, with
 * network.trace_station_pd_null, the addStation PD rejection census by family (card
 * RF-PD).
 *
 * Gate: each section under its own condition, as in the teardown: always (a block);
 * `config_.getNetworkConfig().trace_station_pd_null`.
 *
 * @param v The run at its end (network/runend/RunEnd.hpp).
 * @return 0 (this report does not set the exit code).
 */
int networkSolveStationsRunEnd(const NetworkRunEndView& v);

// ---- End of the run-end reports ----

} // namespace GnssProcessor
